import { useCallback, useEffect, useState } from 'react'
import type { FormEvent, ReactNode } from 'react'
import { auditApi, authApi, brandApi, findingApi, impactApi, reviewApi, reviewDecisionApi, session, submissionApi, teamApi, workspaceApi, rulesApi } from './api/client'
import type { AuditEvent, BrandSource, Finding, Impact, Member, Profile, Workspace, BrandRule } from './api/contracts/index'
import { supabase } from './api/supabase'


type Page = 'overview' | 'library' | 'new-review' | 'history' | 'impact' | 'audit' | 'team'
const nav: { key: Page; label: string; icon: string; group: 'workspace' | 'governance' }[] = [
  { key: 'overview', label: 'Overview', icon: '◫', group: 'workspace' },
  { key: 'new-review', label: 'New review', icon: '＋', group: 'workspace' },
  { key: 'history', label: 'Submissions', icon: '▤', group: 'workspace' },
  { key: 'library', label: 'Brand library', icon: '◇', group: 'governance' },
  { key: 'impact', label: 'Fact changes', icon: '↻', group: 'governance' },
  { key: 'audit', label: 'Audit trail', icon: '⌁', group: 'governance' },
  { key: 'team', label: 'People & access', icon: '♧', group: 'governance' },
]
type RouteState = { page: Page; submissionId: string | null }
function readRoute(): RouteState {
  const [, rawPage, rawId] = window.location.hash.match(/^#\/([^/]+)(?:\/(.+))?$/) ?? []
  const page = nav.some(item => item.key === rawPage) ? rawPage as Page : 'overview'
  return { page, submissionId: rawId ? decodeURIComponent(rawId) : null }
}

function useLoad<T>(loader: () => Promise<T>, deps: unknown[] = []) {
  const [data, setData] = useState<T | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [refreshKey, setRefreshKey] = useState(0)
  const refresh = useCallback(() => setRefreshKey(v => v + 1), [])
  useEffect(() => {
    let active = true
    setLoading(true); setError('')
    loader().then(value => { if (active) setData(value) }).catch(reason => { if (active) setError(errorText(reason)) }).finally(() => { if (active) setLoading(false) })
    return () => { active = false }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [...deps, refreshKey])
  return { data, loading, error, refresh }
}
function errorText(e: unknown) { return e instanceof Error ? e.message : 'Something went wrong. Please try again.' }
function useAction() {
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const run = useCallback(async <T,>(action: () => Promise<T>, success?: string): Promise<T | null> => {
    setBusy(true); setError(''); setNotice('')
    try { const result = await action(); if (success) setNotice(success); return result }
    catch (e) { setError(errorText(e)); return null }
    finally { setBusy(false) }
  }, [])
  return { busy, error, notice, run }
}

export default function App() {
  const [profile, setProfile] = useState<Profile | null>(null)
  const [workspace, setWorkspace] = useState<Workspace | null>(null)
  const [route, setRoute] = useState<RouteState>(readRoute)
  const page = route.page
  const selectedSubmission = route.submissionId
  const [notice, setNotice] = useState('')
  const [booting, setBooting] = useState(true)
  const [bootError, setBootError] = useState('')
  const [restoreAttempt, setRestoreAttempt] = useState(0)
  const navigate = (nextPage: Page, submissionId: string | null = null) => {
    const hash = `#/${nextPage}${submissionId ? `/${encodeURIComponent(submissionId)}` : ''}`
    if (window.location.hash !== hash) window.history.pushState(null, '', hash)
    setRoute({ page: nextPage, submissionId })
  }

  useEffect(() => {
    let active = true
    const restoreProfile = async () => {
      if (!supabase) { if (active) setBooting(false); return }
      const { data: { session: authSession } } = await supabase.auth.getSession()
      if (!authSession) { if (active) setBooting(false); return }
      try {
        const nextProfile = await authApi.me()
        if (active) { setProfile(nextProfile); setWorkspace(nextProfile.workspaces[0] ?? null); setBootError('') }
      } catch (error) { if (active) setBootError(errorText(error)) }
      finally { if (active) setBooting(false) }
    }
    void restoreProfile()
    const subscription = supabase?.auth.onAuthStateChange((event, authSession) => {
      if (event === 'SIGNED_IN' && authSession) window.setTimeout(() => { if (active) void restoreProfile() }, 0)
      if (event === 'SIGNED_OUT') { setProfile(null); setWorkspace(null); setBooting(false) }
    }).data.subscription
    return () => { active = false; subscription?.unsubscribe() }
  }, [restoreAttempt])
  useEffect(() => {
    const expire = () => { setProfile(null); setWorkspace(null); navigate('overview') }
    window.addEventListener('proofline:session-expired', expire)
    return () => window.removeEventListener('proofline:session-expired', expire)
  }, [])
  useEffect(() => {
    const syncRoute = () => setRoute(readRoute())
    window.addEventListener('popstate', syncRoute)
    window.addEventListener('hashchange', syncRoute)
    return () => { window.removeEventListener('popstate', syncRoute); window.removeEventListener('hashchange', syncRoute) }
  }, [])

  const signedIn = useCallback((p: Profile) => { setProfile(p); setWorkspace(p.workspaces[0] ?? null) }, [])
  const signOut = () => { session.clear(); setProfile(null); setWorkspace(null); setBootError(''); navigate('overview') }
  if (bootError && !profile) return <div className="min-h-screen grid place-items-center bg-paper p-6 text-ink"><div className="panel max-w-lg p-8 text-center"><div className="eyebrow">PROOFLINE CONNECTION</div><h1 className="mt-3 text-2xl">Could not load your workspace</h1><p className="mt-3 text-muted">{bootError}</p><div className="mt-6 flex justify-center gap-3"><button className="button button-primary" onClick={() => { setBootError(''); setBooting(true); setRestoreAttempt(v => v + 1) }}>Try again</button><button className="button button-secondary" onClick={signOut}>Sign out</button></div></div></div>
  if (booting) return <div className="min-h-screen grid place-items-center bg-paper text-muted"><div className="flex items-center gap-3"><span className="spinner" /> Restoring your secure session…</div></div>
  if (!profile) return <AuthPage onSignedIn={signedIn} />
  if (!workspace) return <WorkspaceSetup profile={profile} onCreated={w => { const next = { id: w.id, name: w.name, role: 'owner' as const }; setProfile({ ...profile, workspaces: [...profile.workspaces, next] }); setWorkspace(next) }} onSignOut={signOut} />

  const title = selectedSubmission ? 'Review details' : nav.find(n => n.key === page)?.label ?? 'Overview'
  return <div className="app-shell min-h-screen bg-paper text-ink">
    <aside className="sidebar">
      <button type="button" onClick={() => navigate('overview')} className="brandmark brandmark-button" aria-label="Proofline home"><span className="brandmark-icon">P</span><span>proofline<span className="brandmark-dot">.</span></span></button>
      <WorkspacePicker profile={profile} current={workspace} onChange={setWorkspace} />
      <div className="sidebar-label">WORKSPACE</div>
      <nav aria-label="Main navigation" className="side-nav">{nav.filter(n => n.group === 'workspace').map(item => <NavButton key={item.key} item={item} active={page === item.key && !selectedSubmission} onClick={() => navigate(item.key)} />)}</nav>
      <div className="sidebar-label governance-label">GOVERNANCE</div>
      <nav aria-label="Governance" className="side-nav">{nav.filter(n => n.group === 'governance').map(item => <NavButton key={item.key} item={item} active={page === item.key && !selectedSubmission} onClick={() => navigate(item.key)} />)}</nav>
      <div className="sidebar-bottom"><div className="help-card"><div className="help-icon">i</div><div><b>Evidence first</b><p>Every decision stays connected to its source.</p></div></div><div className="profile-row"><div className="avatar">{profile.user.name.trim().slice(0, 1).toUpperCase()}</div><div className="profile-meta"><b>{profile.user.name}</b><span>{profile.user.email}</span></div><button className="icon-button signout" type="button" title="Sign out" aria-label="Sign out" onClick={signOut}>↗</button></div></div>
    </aside>
    <div className="content-wrap">
      <header className="topbar"><div className="breadcrumbs"><span>Workspace</span><span className="crumb-slash">/</span><strong>{title}</strong></div><div className="topbar-actions"><span className="connection"><span className="connection-dot" /> Workspace connected</span><button className="button button-primary button-small" type="button" onClick={() => navigate('new-review')}><span>＋</span> New review</button></div></header>
      <main id="main" className="page-content">
        {page === 'overview' && <Dashboard workspace={workspace} onNavigate={navigate} onOpen={id => navigate('history', id)} />}
        {page === 'library' && <Library workspace={workspace} />}
        {page === 'new-review' && <NewReview workspace={workspace} onCreated={id => navigate('history', id)} />}
        {page === 'history' && (selectedSubmission ? <SubmissionView workspace={workspace} id={selectedSubmission} onBack={() => navigate('history')} /> : <History workspace={workspace} onOpen={id => navigate('history', id)} />)}
        {page === 'impact' && <ImpactQueue workspace={workspace} />}
        {page === 'audit' && <AuditPage workspace={workspace} />}
        {page === 'team' && <TeamPage workspace={workspace} />}
      </main>
      <footer className="app-footer"><span>Proofline</span><span>Brand decisions, with a paper trail.</span></footer>
    </div>
    {notice && <div role="status" className="toast">{notice}<button aria-label="Dismiss notification" onClick={() => setNotice('')}>×</button></div>}
  </div>
}

function NavButton({ item, active, onClick }: { item: typeof nav[number]; active: boolean; onClick: () => void }) { return <button type="button" className={`nav-item ${active ? 'nav-active' : ''}`} onClick={onClick}><span className="nav-glyph" aria-hidden="true">{item.icon}</span><span>{item.label}</span>{item.key === 'impact' && <span className="nav-badge" aria-label="Fact change review queue">↗</span>}</button> }
function WorkspacePicker({ profile, current, onChange }: { profile: Profile; current: Workspace; onChange: (w: Workspace) => void }) {
  const [open, setOpen] = useState(false)
  return <div className="workspace-picker"><button className="workspace-select" type="button" onClick={() => setOpen(v => !v)} aria-expanded={open}><span className="workspace-sigil">{current.id.slice(0, 1).toUpperCase()}</span><span className="workspace-copy"><b>Workspace</b><small>{current.name || current.id.slice(0, 8)}</small></span><span className="chevron">⌄</span></button>
    {open && <div className="workspace-menu" role="menu">{profile.workspaces.map(w => <button role="menuitem" key={w.id} type="button" onClick={() => { onChange(w); setOpen(false) }}><span className="workspace-sigil small-sigil">{w.id.slice(0, 1).toUpperCase()}</span><span><b>{w.name || w.id.slice(0, 8)}</b><small>{w.role.replace('_', ' ')}</small></span>{w.id === current.id && <span className="check">✓</span>}</button>)}</div>}
  </div>
}

function PageHeading({ eyebrow, title, subtitle, action }: { eyebrow?: string; title: string; subtitle: string; action?: ReactNode }) { return <div className="page-heading"><div>{eyebrow && <div className="eyebrow">{eyebrow}</div>}<h1>{title}</h1><p>{subtitle}</p></div>{action && <div className="heading-action">{action}</div>}</div> }
function Panel({ children, className = '' }: { children: ReactNode; className?: string }) { return <section className={`panel ${className}`}>{children}</section> }
function Feedback({ error, notice }: { error?: string; notice?: string }) { return <>{error && <div className="alert alert-error" role="alert"><span>!</span><div><b>Could not complete that request</b><p>{error}</p></div></div>}{notice && <div className="alert alert-success" role="status"><span>✓</span><div>{notice}</div></div>}</> }
function LoadState({ loading, error, empty, onRetry }: { loading: boolean; error: string; empty?: boolean; onRetry?: () => void }) { if (loading) return <div className="load-state"><span className="spinner" /> Loading workspace data…</div>; if (error) return <div className="inline-error"><span>{error}</span>{onRetry && <button className="text-button" onClick={onRetry}>Try again</button>}</div>; if (empty) return <></>; return null }
function EmptyState({ icon = '◇', title, body, action }: { icon?: string; title: string; body: string; action?: React.ReactNode }) { return <div className="empty-state"><div className="empty-illustration"><span className="empty-orbit orbit-one" /><span className="empty-orbit orbit-two" /><span className="empty-icon">{icon}</span></div><h3>{title}</h3><p>{body}</p>{action && <div className="empty-action">{action}</div>}</div> }
function StatCard({ label, value, note, icon, tone }: { label: string; value: string | number; note: string; icon: string; tone?: string }) { return <div className="stat-card"><div className="stat-top"><span>{label}</span><span className={`stat-icon ${tone ?? ''}`}>{icon}</span></div><div className="stat-value">{value}</div><div className="stat-note">{note}</div></div> }

function Dashboard({ workspace, onNavigate, onOpen }: { workspace: Workspace; onNavigate: (p: Page) => void; onOpen: (id: string) => void }) {
  const dashboard = useLoad(() => workspaceApi.summary(workspace.id), [workspace.id])
  const sources = useLoad(() => brandApi.list(workspace.id), [workspace.id])
  const submissions = useLoad(() => submissionApi.list(workspace.id), [workspace.id])
  const impacts = useLoad(() => impactApi.list(workspace.id), [workspace.id])
  const error = dashboard.error || sources.error || submissions.error || impacts.error
  const records = submissions.data ?? []
  const inReview = records.filter(r => r.status === 'in_review').length
  const approved = records.filter(r => r.status === 'approved').length
  const awaiting = dashboard.data?.impact_review_required ?? impacts.data?.filter(i => i.state === 'needs_review').length
  const recent = records.slice(0, 5)
  return <>
    <div className="welcome-strip"><div className="welcome-copy"><span className="welcome-kicker"><span className="sparkle">✳</span> BRAND GOVERNANCE WORKSPACE</span><h1>Keep every claim <em>accountable.</em></h1><p>Review content against approved facts. Trace each decision back to the evidence.</p><button type="button" className="button button-primary" onClick={() => onNavigate('new-review')}>Start a review <span aria-hidden="true">→</span></button></div><div className="welcome-art" aria-hidden="true"><div className="orbit-ring ring-a" /><div className="orbit-ring ring-b" /><div className="orbit-center"><span className="orbit-check">✓</span></div><div className="orbit-node node-a">F</div><div className="orbit-node node-b">✓</div><div className="orbit-node node-c">↗</div><div className="orbit-caption">TRACEABLE BY DESIGN</div></div><div className="welcome-stamp"><span>✳</span> TRUST, VERIFIED</div></div>
    <PageHeading eyebrow="YOUR WORKSPACE" title="Overview" subtitle="A live view of your brand library and review workflow." action={<button className="button button-secondary" onClick={() => { dashboard.refresh(); sources.refresh(); submissions.refresh(); impacts.refresh() }}>↻ <span>Refresh</span></button>} />
    <LoadState loading={dashboard.loading || sources.loading || submissions.loading || impacts.loading} error={error} onRetry={() => { dashboard.refresh(); sources.refresh(); submissions.refresh(); impacts.refresh() }} />
    {!error && <div className="stats-grid"><StatCard icon="◇" label="Approved facts" value={dashboard.data?.approved_facts ?? '—'} note="From your versioned brand library" tone="stat-blue" /><StatCard icon="▤" label="Submissions" value={dashboard.data?.submissions ?? records.length} note="Persisted in this workspace" tone="stat-violet" /><StatCard icon="◷" label="In review" value={inReview} note={inReview ? 'Awaiting a human decision' : 'No submissions awaiting review'} tone="stat-amber" /><StatCard icon="↻" label="Fact changes" value={awaiting ?? '—'} note="Items requiring re-review" tone="stat-teal" /></div>}
    <div className="dashboard-grid"><Panel className="recent-panel"><div className="panel-heading"><div><h2>Recent submissions</h2><p>Latest content submitted to this workspace</p></div><button type="button" className="text-button" onClick={() => onNavigate('history')}>View all <span>→</span></button></div>
      <LoadState loading={submissions.loading} error={submissions.error} empty={!records.length} onRetry={submissions.refresh} />{!submissions.loading && !submissions.error && (recent.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Content</th><th>Status</th><th>Owner</th><th aria-label="Open" /></tr></thead><tbody>{recent.map(s => <tr key={s.id} onClick={() => onOpen(s.id)} tabIndex={0} onKeyDown={e => e.key === 'Enter' && onOpen(s.id)}><td><div className="submission-title"><span className="file-tile">▤</span><span><b>{s.title}</b><small>Added to workspace</small></span></div></td><td><StatusPill status={s.status} /></td><td><span className="owner-mark">{s.owner.slice(0, 1).toUpperCase()}</span></td><td><span className="row-arrow">→</span></td></tr>)}</tbody></table></div> : <EmptyState icon="▤" title="Your review history starts here" body="Submissions you create will appear here, along with their review and decision history." action={<button className="button button-secondary" onClick={() => onNavigate('new-review')}>Create a submission</button>} />)}</Panel>
      <div className="right-stack"><Panel className="library-summary"><div className="panel-heading"><div><h2>Brand library</h2><p>Approved facts available to the review engine</p></div><span className="summary-icon">◇</span></div><LoadState loading={sources.loading} error={sources.error} empty={!sources.data?.length} onRetry={sources.refresh} />{!sources.loading && !sources.error && (sources.data?.length ? <><div className="library-count"><strong>{sources.data.length}</strong><span>source{sources.data.length === 1 ? '' : 's'}<br />tracked</span></div><div className="micro-list">{sources.data.slice(0, 3).map(s => <div key={s.id}><span className="micro-dot" /><span>{s.title}</span><small>{s.versions.filter(v => Boolean(v.approved_by)).length} approved</small></div>)}</div><button className="text-button full-link" onClick={() => onNavigate('library')}>Open brand library <span>→</span></button></> : <div className="mini-empty">No approved sources yet.<button className="text-button" onClick={() => onNavigate('library')}>Add your first fact →</button></div>)}</Panel>
        <Panel className="decision-card"><div className="decision-icon">✓</div><div><div className="eyebrow">HUMAN IN THE LOOP</div><h2>Evidence supports review.<br />People make decisions.</h2><p>Proofline records the context behind every review and approval.</p></div><button className="text-button" onClick={() => onNavigate('audit')}>Explore the audit trail <span>→</span></button></Panel>
      </div>
    </div>
    {!error && records.length > 0 && <div className="overview-footnote"><span className="footnote-mark">i</span><span>Review findings show rule matches and stored evidence. A clean check does not prove a claim is true.</span><span className="footnote-count">{approved} approved submission{approved === 1 ? '' : 's'}</span></div>}
  </>
}

function StatusPill({ status }: { status: string }) { const names: Record<string, string> = { in_review: 'In review', awaiting_evidence: 'Awaiting evidence', processing_evidence: 'Processing evidence', ready_for_review: 'Ready for review', changes_requested: 'Changes requested', draft: 'Draft', approved: 'Approved', rejected: 'Rejected', needs_review: 'Needs review', revalidated: 'Revalidated', change_required: 'Change required', not_affected: 'Not affected' }; return <span className={`status-pill status-${status}`}><span />{names[status] ?? status.replaceAll('_', ' ')}</span> }

function AuthPage({ onSignedIn }: { onSignedIn: (p: Profile) => void }) {
  const [register, setRegister] = useState(false), [email, setEmail] = useState(''), [name, setName] = useState(''), [password, setPassword] = useState('')
  const [verificationPending, setVerificationPending] = useState(false)
  const [authNotice, setAuthNotice] = useState('')
  const emailRedirectTo = `${window.location.origin}${window.location.pathname}?verified=1`
  const action = useAction()
  useEffect(() => {
    if (new URLSearchParams(window.location.search).has('verified')) {
      window.history.replaceState(null, '', `${window.location.pathname}${window.location.hash}`)
      setAuthNotice('Your email is verified. Sign in to continue.')
    }
  }, [])
  const submit = async (e: FormEvent) => {
    e.preventDefault()
    if (!email.includes('@')) { void action.run(async () => { throw new Error('Enter a valid email address.') }); return }
    if (password.length < 8) { void action.run(async () => { throw new Error('Use at least 8 characters for your password.') }); return }
    if (register && !name.trim()) { void action.run(async () => { throw new Error('Enter your name to create an account.') }); return }
    if (register) {
      const result = await action.run(() => authApi.register(email.trim(), name.trim(), password, emailRedirectTo), 'Check your inbox for a verification link.')
      if (result) {
        setEmail(result.email || email.trim()); setPassword('')
        if (result.verification_required) setVerificationPending(true)
        else { const profile = await action.run(() => authApi.me()); if (profile) onSignedIn(profile) }
      }
      return
    }
    const profile = await action.run(async () => { await authApi.login(email.trim(), password); return authApi.me() })
    if (profile) onSignedIn(profile)
  }
  const resendVerification = () => void action.run(() => authApi.resendVerification(email.trim(), emailRedirectTo), 'If that address has a pending signup, a new confirmation link is on its way.')
  return <div className="auth-layout"><section className="auth-brand"><a className="brandmark auth-logo" href="/"><span className="brandmark-icon">P</span><span>proofline<span className="brandmark-dot">.</span></span></a><div className="auth-promise"><span className="welcome-kicker"><span className="sparkle">✳</span> BRAND GOVERNANCE, MADE CLEAR</span><h1>Make every brand claim <em>traceable.</em></h1><p>Keep facts, reviews, and human decisions connected in one calm workspace.</p><div className="auth-proof"><span>✓</span><div><b>Built around evidence</b><small>Every finding has a source, status, or stated uncertainty.</small></div></div><div className="auth-proof"><span>↗</span><div><b>Changes leave a trail</b><small>Versions and decisions stay visible over time.</small></div></div></div><div className="auth-side-note">Proofline <span>·</span> Brand governance workspace</div></section><section className="auth-main"><div className="auth-form-wrap"><div className="eyebrow">YOUR WORKSPACE AWAITS</div><h2>{verificationPending ? 'Verify your email' : register ? 'Create your account' : 'Welcome back'}</h2><p>{verificationPending ? `We sent a verification link to ${email}. Confirm your address before signing in.` : register ? 'Start building a clear record of your brand.' : 'Sign in to continue to Proofline.'}</p><Feedback error={action.error} notice={authNotice || action.notice} />{verificationPending ? <div className="verification-panel"><div className="verification-icon">✉</div><b>Check your inbox</b><span>Open the Supabase confirmation link to verify your email. You can return here after confirming.</span><button type="button" className="button button-secondary button-wide" onClick={resendVerification} disabled={action.busy}>{action.busy ? 'Sending…' : 'Resend verification email'}</button><button type="button" className="text-button" onClick={() => { setVerificationPending(false); setRegister(false) }}>Back to sign in</button></div> : <><form onSubmit={submit} className="form-stack">{register && <Field label="Your name" value={name} onChange={setName} placeholder="Name" autoComplete="name" />}<Field label="Work email" value={email} onChange={setEmail} placeholder="you@company.com" type="email" autoComplete="email" /><Field label="Password" value={password} onChange={setPassword} placeholder="At least 8 characters" type="password" autoComplete={register ? 'new-password' : 'current-password'} /><button disabled={action.busy} className="button button-primary button-wide" type="submit">{action.busy ? 'Connecting…' : register ? 'Create account' : 'Sign in'} <span>→</span></button></form><div className="auth-switch">{register ? 'Already have an account?' : 'New to Proofline?'} <button type="button" className="text-button" onClick={() => { setRegister(v => !v); void action.run(async () => undefined); setAuthNotice('') }}>{register ? 'Sign in' : 'Create an account'}</button></div></>}<div className="auth-security"><span>⌑</span> Email confirmation is managed by Supabase Auth.</div></div><div className="auth-bottom">Supabase securely manages your sign-in session. Workspace data is loaded from the Proofline API.</div></section></div>
}
function Field({ label, value, onChange, placeholder, type = 'text', autoComplete, required = true }: { label: string; value: string; onChange: (s: string) => void; placeholder?: string; type?: string; autoComplete?: string; required?: boolean }) { return <label className="field"><span>{label}</span><input type={type} value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} autoComplete={autoComplete} required={required} /></label> }
function WorkspaceSetup({ profile, onCreated, onSignOut }: { profile: Profile; onCreated: (w: { id: string; name: string }) => void; onSignOut: () => void }) {
  const [name, setName] = useState(''); const action = useAction()
  const create = async (e: FormEvent) => { e.preventDefault(); if (name.trim().length < 2) { action.run(async () => { throw new Error('Workspace name must be at least 2 characters.') }); return } const w = await action.run(() => workspaceApi.create(name.trim()), 'Workspace created.'); if (w) onCreated(w) }
  return <div className="setup-layout"><div className="setup-card"><a className="brandmark" href="/"><span className="brandmark-icon">P</span><span>proofline<span className="brandmark-dot">.</span></span></a><div className="setup-mark">◈</div><div className="eyebrow">A NEW PLACE TO BEGIN</div><h1>Create your workspace</h1><p>Your brand facts, reviews, and decisions live together in a private workspace.</p><Feedback error={action.error} notice={action.notice} /><form className="form-stack" onSubmit={create}><Field label="Workspace name" value={name} onChange={setName} placeholder="Your organization" /><button className="button button-primary button-wide" disabled={action.busy}>{action.busy ? 'Creating…' : 'Create workspace'} <span>→</span></button></form><button className="text-button setup-signout" onClick={onSignOut}>Sign out from {profile.user.email}</button></div></div>
}

function Library({ workspace }: { workspace: Workspace }) {
  const [tab, setTab] = useState<'facts' | 'rules'>('facts')
  return <><PageHeading eyebrow="BRAND SOURCE OF TRUTH" title="Brand library" subtitle="Manage the approved facts and rules used by Proofline reviews." action={<span className="role-chip">{workspace.role.replace('_', ' ')}</span>} /><div className="filter-tabs library-tabs"><button type="button" className={tab === 'facts' ? 'filter-active' : ''} onClick={() => setTab('facts')}>Brand facts</button><button type="button" className={tab === 'rules' ? 'filter-active' : ''} onClick={() => setTab('rules')}>Brand rules</button></div>{tab === 'facts' ? <FactsLibrary workspace={workspace} /> : <RulesLibrary workspace={workspace} />}</>
}
function FactsLibrary({ workspace }: { workspace: Workspace }) {
  const list = useLoad(() => brandApi.list(workspace.id), [workspace.id]); const action = useAction()
  const [form, setForm] = useState({ key: '', title: '', value_type: 'text', subject_terms: '', body: '' })
  const [draft, setDraft] = useState<Record<string, { body: string; value: string }>>({})
  const create = async (e: FormEvent) => {
    e.preventDefault()
    const subjectTerms = form.subject_terms.split(',').map(term => term.trim()).filter(Boolean)
    if (!form.key.trim() || !form.title.trim() || !form.body.trim()) { void action.run(async () => { throw new Error('Enter a fact key, display name, and approved value.') }); return }
    if (form.value_type !== 'text' && !subjectTerms.length) { void action.run(async () => { throw new Error('Add at least one subject term for number, money, and date facts.') }); return }
    const item = await action.run(() => brandApi.create(workspace.id, { key: form.key.trim(), title: form.title.trim(), value_type: form.value_type, subject_terms: subjectTerms, body: form.body.trim() }), 'Approved fact created. New reviews can use it immediately.')
    if (item) { setForm({ key: '', title: '', value_type: 'text', subject_terms: '', body: '' }); list.refresh() }
  }
  return <><Feedback error={action.error} notice={action.notice} /><div className="library-layout"><Panel className="library-list-panel"><div className="panel-heading"><div><h2>Brand facts</h2><p>Approved fact versions are used during review</p></div><span className="panel-counter">{list.data?.length ?? '—'}</span></div><LoadState loading={list.loading} error={list.error} empty={!list.data?.length} onRetry={list.refresh} />{!list.loading && !list.error && (list.data?.length ? <div className="fact-list">{list.data.map(source => <FactCard key={source.id} source={source} workspace={workspace} action={action} draft={draft[source.id]} setDraft={value => setDraft(d => ({ ...d, [source.id]: value }))} refresh={list.refresh} />)}</div> : <EmptyState title="No brand facts yet" body="Add approved wording and the terms that identify where each fact applies." />)}</Panel><Panel className="create-fact-panel"><div className="form-panel-header"><span className="form-panel-icon">＋</span><div><h2>Add a brand fact</h2><p>Facts are versioned and available to new reviews as soon as approved.</p></div></div><form className="form-stack" onSubmit={create}><Field label="Fact key" value={form.key} onChange={v => setForm({ ...form, key: v })} placeholder="e.g. pricing_standard" /><Field label="Display name" value={form.title} onChange={v => setForm({ ...form, title: v })} placeholder="e.g. Standard plan seats" /><label className="field"><span>Value type</span><select value={form.value_type} onChange={e => setForm({ ...form, value_type: e.target.value })}><option value="text">Text</option><option value="number">Number</option><option value="money">Money</option><option value="date">Date</option></select></label><Field label="Subject terms" value={form.subject_terms} onChange={v => setForm({ ...form, subject_terms: v })} placeholder="Comma-separated, e.g. seats, plan" /><Field label="Approved value" value={form.body} onChange={v => setForm({ ...form, body: v })} placeholder="Exact approved wording or value" /><div className="form-hint"><span>i</span><span>Money and dates are validated by the API. Edits create immutable versions and flag dependent submissions.</span></div><button className="button button-primary button-wide" disabled={action.busy || workspace.role !== 'owner' && workspace.role !== 'editor'}>{action.busy ? 'Saving…' : 'Save approved fact'} <span>→</span></button>{workspace.role !== 'owner' && workspace.role !== 'editor' && <small className="permission-note">Only workspace owners and editors can manage facts.</small>}</form></Panel></div></>
}
function FactCard({ source, workspace, action, draft, setDraft, refresh }: { source: BrandSource; workspace: Workspace; action: ReturnType<typeof useAction>; draft?: { body: string; value: string }; setDraft: (v: { body: string; value: string }) => void; refresh: () => void }) {
  const approved = source.versions[0]?.approved_by != null
  return <article className="fact-card"><div className="fact-top"><div className="fact-symbol">◇</div><div className="fact-title"><span className="fact-key">{source.key}</span><h3>{source.title}</h3><span className="fact-unit">{source.value_type} · {source.unit_re || 'no subject terms'}</span></div><span className={`approval-label ${approved ? 'approval-yes' : 'approval-pending'}`}><span />{approved ? 'Approved fact' : 'Draft fact'}</span></div><div className="version-list">{source.versions.map(version => <div className="version-row" key={version.id}><div className="version-marker"><span /></div><div className="version-content"><div className="version-meta"><b>Version {version.no}</b><span>{new Date(version.created).toLocaleDateString()}</span><span className={`tiny-status ${version.approved_by ? 'tiny-approved' : 'tiny-pending'}`}>{version.approved_by ? 'Approved' : 'Draft'}</span></div><p>{version.body}</p><small>Type: {version.value_type}</small></div>{!version.approved_by && (workspace.role === 'owner' || workspace.role === 'editor') && <button className="button button-secondary button-xs" disabled={action.busy} onClick={async () => { const result = await action.run(() => brandApi.approve(workspace.id, source.id), 'Fact approved.'); if (result) refresh() }}>Approve fact</button>}</div>)}</div><details className="version-add"><summary>Add a new version</summary><div className="version-form"><Field label="Updated approved value" value={draft?.body ?? ''} onChange={body => setDraft({ body, value: '' })} placeholder="Enter revised wording or value" /><button className="button button-secondary button-small" disabled={action.busy || workspace.role !== 'owner' && workspace.role !== 'editor'} onClick={async () => { if (!draft?.body.trim()) { void action.run(async () => { throw new Error('Enter the updated fact value.') }); return } const result = await action.run(() => brandApi.addVersion(workspace.id, source.id, draft.body), 'New fact version saved.'); if (result) { setDraft({ body: '', value: '' }); refresh() } }}>{action.busy ? 'Saving…' : 'Save new version'}</button></div>{workspace.role !== 'owner' && workspace.role !== 'editor' && <small className="permission-note">Your role cannot edit facts.</small>}</details></article>
}
function RulesLibrary({ workspace }: { workspace: Workspace }) {
  const list = useLoad(() => rulesApi.list(workspace.id), [workspace.id]); const action = useAction()
  const [form, setForm] = useState({ key: '', rule_type: 'prohibited_phrase', description: '', patterns: '', severity: 'medium', applies_to: 'text' })
  const create = async (e: FormEvent) => {
    e.preventDefault(); const patterns = form.patterns.split(',').map(value => value.trim()).filter(Boolean)
    if (!form.key.trim() || !form.description.trim() || !patterns.length) { void action.run(async () => { throw new Error('Enter a key, description, and at least one pattern.') }); return }
    const result = await action.run(() => rulesApi.create(workspace.id, { key: form.key.trim(), rule_type: form.rule_type, description: form.description.trim(), patterns, severity: form.severity as 'high' | 'medium' | 'low', applies_to: form.applies_to.split(',').map(value => value.trim()).filter(Boolean) }), 'Approved brand rule created.')
    if (result) { setForm({ key: '', rule_type: 'prohibited_phrase', description: '', patterns: '', severity: 'medium', applies_to: 'text' }); list.refresh() }
  }
  return <><Feedback error={action.error} notice={action.notice} /><div className="library-layout"><Panel className="library-list-panel"><div className="panel-heading"><div><h2>Versioned rules</h2><p>Rules are evaluated against the content types they target.</p></div><span className="panel-counter">{list.data?.length ?? '—'}</span></div><LoadState loading={list.loading} error={list.error} empty={!list.data?.length} onRetry={list.refresh} />{!list.loading && !list.error && (list.data?.length ? <div className="fact-list">{list.data.map(rule => <RuleCard key={rule.id} rule={rule} workspace={workspace} refresh={list.refresh} />)}</div> : <EmptyState title="No brand rules yet" body="Create a rule to flag prohibited phrases, require terms, or identify claims that need evidence." />)}</Panel><Panel className="create-fact-panel"><div className="form-panel-header"><span className="form-panel-icon">＋</span><div><h2>Add a brand rule</h2><p>Rules are saved as approved, versioned backend records.</p></div></div><form className="form-stack" onSubmit={create}><Field label="Rule key" value={form.key} onChange={v => setForm({ ...form, key: v })} placeholder="e.g. avoid_guarantee" /><label className="field"><span>Rule type</span><select value={form.rule_type} onChange={e => setForm({ ...form, rule_type: e.target.value })}><option value="prohibited_phrase">Prohibited phrase</option><option value="required_term">Required term</option><option value="approved_name">Approved name</option><option value="claim_requires_evidence">Claim needs evidence</option></select></label><Field label="Description" value={form.description} onChange={v => setForm({ ...form, description: v })} placeholder="Explain what the rule checks" /><Field label="Patterns" value={form.patterns} onChange={v => setForm({ ...form, patterns: v })} placeholder="Comma-separated phrases" /><label className="field"><span>Severity</span><select value={form.severity} onChange={e => setForm({ ...form, severity: e.target.value })}><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select></label><Field label="Applies to" value={form.applies_to} onChange={v => setForm({ ...form, applies_to: v })} placeholder="Content types, e.g. text, pdf" /><button className="button button-primary button-wide" disabled={action.busy || workspace.role !== 'owner' && workspace.role !== 'editor'}>{action.busy ? 'Saving…' : 'Save approved rule'} <span>→</span></button>{workspace.role !== 'owner' && workspace.role !== 'editor' && <small className="permission-note">Only owners and editors can manage rules.</small>}</form></Panel></div></>
}
function RuleCard({ rule, workspace, refresh }: { rule: BrandRule; workspace: Workspace; refresh: () => void }) {
  const [description, setDescription] = useState(rule.description); const [patterns, setPatterns] = useState(rule.patterns.join(', ')); const [severity, setSeverity] = useState(rule.severity); const [appliesTo, setAppliesTo] = useState(rule.applies_to.join(', ')); const action = useAction()
  const save = async () => {
    const cleanPatterns = patterns.split(',').map(value => value.trim()).filter(Boolean); const cleanApplies = appliesTo.split(',').map(value => value.trim()).filter(Boolean)
    if (!description.trim() || !cleanPatterns.length) { void action.run(async () => { throw new Error('A rule description and at least one pattern are required.') }); return }
    const updated = await action.run(() => rulesApi.update(rule.ws, rule.id, { rule_type: rule.rule_type, description: description.trim(), patterns: cleanPatterns, severity, applies_to: cleanApplies, change_note: 'Updated from the Proofline frontend' }), 'Rule updated as a new version.')
    if (updated) refresh()
  }
  return <article className="fact-card"><div className="fact-top"><div className="fact-symbol">◇</div><div className="fact-title"><span className="fact-key">{rule.key} · {rule.rule_type.replaceAll('_', ' ')}</span><h3>{rule.description}</h3><span className="fact-unit">{rule.severity} · {rule.applies_to.join(', ') || 'all supported types'}</span></div><span className="approval-label approval-yes"><span />Approved</span></div><div className="version-list">{rule.versions.map(version => <div className="version-row" key={version.id}><div className="version-marker"><span /></div><div className="version-content"><div className="version-meta"><b>Version {version.no}</b><span>{new Date(version.created).toLocaleDateString()}</span></div><p>{version.body}</p></div></div>)}</div>{workspace.role === 'owner' || workspace.role === 'editor' ? <details className="version-add"><summary>Edit rule (creates a new version)</summary><div className="form-stack"><Field label="Description" value={description} onChange={setDescription} /><Field label="Patterns" value={patterns} onChange={setPatterns} /><label className="field"><span>Severity</span><select value={severity} onChange={e => setSeverity(e.target.value as typeof severity)}><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select></label><Field label="Applies to" value={appliesTo} onChange={setAppliesTo} /><Feedback error={action.error} notice={action.notice} /><button className="button button-secondary button-small" disabled={action.busy} onClick={() => void save()}>{action.busy ? 'Saving…' : 'Save new rule version'}</button></div></details> : null}</article>
}function NewReview({ workspace, onCreated }: { workspace: Workspace; onCreated: (id: string) => void }) {
  const [title, setTitle] = useState(''); const [text, setText] = useState(''); const [sourceMode, setSourceMode] = useState<'text' | 'file' | 'url'>('text'); const [file, setFile] = useState<File | null>(null); const [evidence, setEvidence] = useState<File[]>([]); const [url, setUrl] = useState(''); const action = useAction()
  const submit = async (e: FormEvent) => {
    e.preventDefault()
    if (title.trim().length < 2) { void action.run(async () => { throw new Error('Add a title before saving your submission.') }); return }
    if (sourceMode === 'text' && !text.trim()) { void action.run(async () => { throw new Error('Paste the content you want Proofline to review.') }); return }
    if (sourceMode === 'file' && !file) { void action.run(async () => { throw new Error('Choose a document or image to upload.') }); return }
    if (sourceMode === 'url' && !/^https?:\/\//i.test(url.trim())) { void action.run(async () => { throw new Error('Enter a complete public http or https URL.') }); return }
    if (!evidence.length) { void action.run(async () => { throw new Error('Attach at least one supporting TXT, PDF, or DOCX evidence file before saving.') }); return }
    const submission = await action.run(async () => {
      const created = await submissionApi.create(workspace.id, title.trim(), text.trim(), { sourceType: sourceMode, file: file ?? undefined, url: url.trim() || undefined })
      for (const proof of evidence) await submissionApi.addEvidence(workspace.id, created.revision!.id, proof)
      return created
    }, 'Submission and evidence saved.')
    if (submission) onCreated(submission.id)
  }
  return <><PageHeading eyebrow="START WITH THE CONTENT" title="New review" subtitle="Submit a claim and attach supporting proof. Approval requires successfully processed evidence." /><Feedback error={action.error} notice={action.notice} /><div className="review-layout"><Panel className="review-form-panel"><div className="panel-heading"><div><h2>Submission content</h2><p>The claim and evidence are stored as immutable versions.</p></div><span className="draft-indicator"><span /> Evidence required</span></div><div className="source-tabs" role="tablist" aria-label="Content source">{(['text', 'file', 'url'] as const).map((mode, i) => <button key={mode} type="button" role="tab" aria-selected={sourceMode === mode} className={sourceMode === mode ? 'source-tab source-tab-active' : 'source-tab'} onClick={() => setSourceMode(mode)}>{['▤', '↥', '↗'][i]} {['Paste text', 'Upload file', 'Public URL'][i]}</button>)}</div><form onSubmit={submit} className="form-stack"><Field label="Submission title" value={title} onChange={setTitle} placeholder="Give this piece of content a name" />{sourceMode === 'text' ? <label className="field"><span>Claim or content to review</span><textarea className="review-textarea" value={text} onChange={e => setText(e.target.value)} placeholder="Paste the claim or content to check…" rows={12} /><small className="field-caption">The claim is stored as an immutable submission version.</small></label> : sourceMode === 'file' ? <label className="field"><span>Claim document</span><input type="file" accept=".docx,.pdf,.pptx,.png,.jpg,.jpeg,.webp,.html,.txt" onChange={e => setFile(e.target.files?.[0] ?? null)} /><small className="field-caption">The claim file is separate from required proof.</small></label> : <Field label="Public claim URL" value={url} onChange={setUrl} placeholder="https://example.com/page" type="url" />}<label className="field"><span>Supporting evidence (required)</span><input type="file" multiple accept=".txt,.pdf,.docx" onChange={e => setEvidence(Array.from(e.target.files ?? []))} /><small className="field-caption">Upload one or more readable TXT, PDF, or DOCX proof files.</small>{evidence.length > 0 && <small className="field-caption">{evidence.map(item => item.name).join(', ')}</small>}</label><div className="review-form-footer"><span className="word-count">{sourceMode === 'text' ? `${text.trim() ? text.trim().split(/\s+/).length : 0} words` : sourceMode === 'file' ? file?.name ?? 'No claim file selected' : 'URL claim is fetched by the API'}</span><button className="button button-primary" disabled={action.busy || workspace.role !== 'owner' && workspace.role !== 'editor'}>{action.busy ? 'Saving…' : 'Save with evidence'} <span>→</span></button></div>{workspace.role !== 'owner' && workspace.role !== 'editor' && <small className="permission-note">Your workspace role cannot create submissions.</small>}</form></Panel><aside className="review-aside"><div className="aside-step"><span className="step-number">01</span><div><b>Extract claim and proof</b><p>Every evidence file is processed and stored privately.</p></div></div><div className="aside-connector" /><div className="aside-step"><span className="step-number">02</span><div><b>Compare evidence</b><p>The review records actual extracted excerpts and limitations.</p></div></div><div className="aside-connector" /><div className="aside-step"><span className="step-number step-muted">03</span><div><b>Human approval</b><p>Approval is blocked until evidence analysis succeeds.</p></div></div><div className="review-note"><span>i</span><p><b>Evidence is not automatic verification.</b> Contradictions and insufficient evidence remain visible to reviewers.</p></div></aside></div></>
}function History({ workspace, onOpen }: { workspace: Workspace; onOpen: (id: string) => void }) {
  const list = useLoad(() => submissionApi.list(workspace.id), [workspace.id]); const [filter, setFilter] = useState('all')
  const rows = (list.data ?? []).filter(s => filter === 'all' || s.status === filter)
  return <><PageHeading eyebrow="PERSISTED CONTENT" title="Submissions" subtitle="Follow each saved revision through its review and decision." action={<span className="history-total">{list.data?.length ?? '—'} total</span>} /><div className="filter-row"><div className="filter-tabs">{[['all', 'All'], ['draft', 'Drafts'], ['in_review', 'In review'], ['approved', 'Approved']].map(([value, label]) => <button key={value} className={filter === value ? 'filter-active' : ''} onClick={() => setFilter(value)}>{label}{value === 'all' && list.data && <span>{list.data.length}</span>}</button>)}</div><button className="button button-secondary button-small" onClick={list.refresh}>↻ Refresh</button></div><Panel className="history-panel"><LoadState loading={list.loading} error={list.error} empty={!rows.length} onRetry={list.refresh} />{!list.loading && !list.error && (rows.length ? <div className="table-scroll"><table className="data-table history-table"><thead><tr><th>Submission</th><th>Status</th><th>Record ID</th><th /></tr></thead><tbody>{rows.map(s => <tr key={s.id} onClick={() => onOpen(s.id)} tabIndex={0} onKeyDown={e => e.key === 'Enter' && onOpen(s.id)}><td><div className="submission-title"><span className="file-tile">▤</span><span><b>{s.title}</b><small>Revision history and findings</small></span></div></td><td><StatusPill status={s.status} /></td><td><code>{s.id.slice(0, 12)}</code></td><td><button className="icon-button row-arrow" aria-label={`Open ${s.title}`} onClick={e => { e.stopPropagation(); onOpen(s.id) }}>→</button></td></tr>)}</tbody></table></div> : <EmptyState icon="▤" title={filter === 'all' ? 'No submissions yet' : `No ${filter.replace('_', ' ')} submissions`} body="Once a submission is saved through the API, it will appear here with its real status and review record." />)}</Panel></>
}

function SubmissionView({ workspace, id, onBack }: { workspace: Workspace; id: string; onBack: () => void }) {
  const detail = useLoad(() => submissionApi.detail(workspace.id, id), [workspace.id, id]); const action = useAction(); const [text, setText] = useState(''); const [rationale, setRationale] = useState(''); const [newEvidence, setNewEvidence] = useState<File | null>(null); const [evidenceDescription, setEvidenceDescription] = useState(''); const [latestFindings, setLatestFindings] = useState<Finding[] | null>(null)
  useEffect(() => { if (detail.data) { setText(detail.data.revision.text); setLatestFindings(detail.data.findings) } }, [detail.data])
  const d = detail.data
  const saveRevision = async () => { if (!d || !text.trim()) { action.run(async () => { throw new Error('Submission text cannot be empty.') }); return } const saved = await action.run(() => submissionApi.revise(workspace.id, id, text.trim()), 'New revision saved.'); if (saved) detail.refresh() }
  const addEvidence = async () => { if (!d || !newEvidence) return; const saved = await action.run(() => submissionApi.addEvidence(workspace.id, d.revision.id, newEvidence, evidenceDescription), 'Evidence uploaded and processed.'); if (saved) { setNewEvidence(null); setEvidenceDescription(''); detail.refresh() } }
  const runReview = async () => { const res = await action.run(() => reviewApi.run(workspace.id, id)); if (res) detail.refresh() }
  const findings = latestFindings
  return <><button className="back-link" onClick={onBack}>← <span>Back to submissions</span></button><LoadState loading={detail.loading} error={detail.error} onRetry={detail.refresh} />{d && <><PageHeading eyebrow={`SUBMISSION ${d.id.slice(0, 8).toUpperCase()}`} title={d.title} subtitle={`Revision ${d.revision.no} · Created ${new Date(d.revision.created).toLocaleString()}`} action={<StatusPill status={d.status} />} /><Feedback error={action.error} notice={action.notice} /><div className="detail-grid"><div className="detail-main"><Panel><div className="panel-heading"><div><h2>Content snapshot</h2><p>Editing creates a new revision and preserves this one.</p></div><code className="hash-label">SHA · {d.revision.hash.slice(0, 10)}</code></div><textarea className="detail-editor" value={text} readOnly={workspace.role !== 'owner' && workspace.role !== 'editor'} onChange={e => setText(e.target.value)} aria-label="Submission revision text" /><div className="detail-actions"><button className="button button-secondary" disabled={action.busy || text.trim() === d.revision.text || workspace.role !== 'owner' && workspace.role !== 'editor'} title={workspace.role !== 'owner' && workspace.role !== 'editor' ? 'Only an owner or editor can create a revision.' : 'Edit the text to create a new revision.'} onClick={saveRevision}>Save as new revision</button><button className="button button-primary" disabled={action.busy || !d.evidence.length} onClick={runReview}>{action.busy ? 'Reviewing…' : 'Run brand check'} <span>→</span></button></div>{!d.evidence.length && <small className="permission-note">Add processed evidence before running the review.</small>}</Panel><Panel><div className="panel-heading"><div><h2>Supporting evidence</h2><p>Evidence is extracted, stored privately, and shown with its actual text.</p></div><span className="panel-counter">{d.evidence.length}</span></div><label className="field"><span>Add proof for this exact revision</span><input type="file" accept=".txt,.pdf,.docx" onChange={e => setNewEvidence(e.target.files?.[0] ?? null)} /><input value={evidenceDescription} onChange={e => setEvidenceDescription(e.target.value)} placeholder="What does this file prove? (optional)" /><button type="button" className="button button-secondary button-small" disabled={!newEvidence || action.busy || workspace.role !== 'owner' && workspace.role !== 'editor'} onClick={() => void addEvidence()}>Upload evidence</button></label>{d.evidence.length ? <div className="finding-list">{d.evidence.map(item => <article className="finding-card" key={item.id}><div><b>{item.original_filename}</b><small>{item.extraction_status} · {Math.ceil(item.size_bytes / 1024)} KB</small><p>{item.extracted_text.slice(0, 500) || 'No readable text extracted.'}</p>{item.extraction_warnings.map(warning => <small key={warning}>{warning}</small>)}</div></article>)}</div> : <EmptyState icon="⊘" title="Evidence required" body="This claim cannot be reviewed or approved until at least one proof file is processed." />}{d.assessments.length > 0 && <div className="finding-list">{d.assessments.map(item => <article className="finding-card" key={item.id}><div><b>{item.assessment.replaceAll('_', ' ')}</b><p>{item.explanation}</p>{item.excerpt && <small>Excerpt: {item.excerpt}</small>}</div></article>)}</div>}</Panel><Panel><div className="panel-heading"><div><h2>Findings</h2><p>Returned evidence and exact content locations from this review.</p></div>{findings && <span className="panel-counter">{findings.length}</span>}</div>{findings === null ? <EmptyState icon="⌕" title="No review run for this revision" body="Run a brand check to get findings from the connected review engine. Nothing is simulated." action={<button className="button button-secondary" disabled={action.busy} onClick={runReview}>Run brand check</button>} /> : findings.length ? <div className="finding-list">{findings.map(f => <FindingCard key={f.id} finding={f} workspace={workspace} onResolve={async () => { const reason = window.prompt('Why is this finding resolved?'); if (!reason?.trim()) return; const r = await action.run(() => findingApi.resolve(workspace.id, f.id, reason.trim()), 'Finding marked resolved.'); if (r) detail.refresh() }} busy={action.busy} />)}</div> : <div className="clean-result"><span>✓</span><div><b>No deterministic findings were returned</b><p>This is not proof that every claim is true. Review the content and available facts with care.</p></div></div>}</Panel></div><aside className="detail-side"><Panel className="process-panel"><div className="eyebrow">REVIEW WORKFLOW</div><h2>Review record</h2><div className="process-step"><span className="process-mark complete">✓</span><div><b>Content saved</b><small>Revision {d.revision.no} · immutable snapshot</small></div></div><div className="process-line" /><div className="process-step"><span className={`process-mark ${findings !== null ? 'complete' : ''}`}>{findings !== null ? '✓' : '2'}</span><div><b>Deterministic check</b><small>{findings === null ? 'Not run on this revision' : 'Results saved by the backend'}</small></div></div><div className="process-line" /><div className="process-step"><span className={`process-mark ${d.status === 'approved' ? 'complete' : ''}`}>{d.status === 'approved' ? '✓' : '3'}</span><div><b>Human decision</b><small>{d.status.replaceAll('_', ' ')}</small></div></div></Panel>{d.status === 'draft' && <Panel><div className="eyebrow">REVIEW REQUIRED</div><p className="side-copy">Run a review on this version first. The backend records decisions directly against a successful review run.</p></Panel>}{d.status === 'in_review' && <Panel><div className="eyebrow">REVIEWER DECISION</div><label className="field"><span>Rationale</span><textarea value={rationale} onChange={e => setRationale(e.target.value)} placeholder="Explain the decision (required)" rows={3} /></label><div className="decision-buttons">{[['approved', 'Approve'], ['changes_requested', 'Request changes'], ['rejected', 'Reject']].map(([decision, label]) => <button key={decision} className={`button ${decision === 'approved' ? 'button-primary' : 'button-secondary'} button-wide`} disabled={action.busy || !rationale.trim() || workspace.role !== 'owner' && workspace.role !== 'reviewer'} onClick={async () => { const res = await action.run(() => reviewDecisionApi.decide(workspace.id, id, d.revision.id, decision, rationale.trim()), 'Decision recorded in the audit history.'); if (res) detail.refresh() }}>{label}</button>)}</div>{workspace.role !== 'owner' && workspace.role !== 'reviewer' && <small className="permission-note">Only an authorized reviewer can decide.</small>}</Panel>}{d.decisions.length > 0 && <Panel><div className="eyebrow">DECISION HISTORY</div>{d.decisions.map(dec => <div className="decision-history" key={dec.id}><StatusPill status={dec.decision} /><p>{dec.rationale}</p><small>{new Date(dec.created).toLocaleString()}</small></div>)}</Panel>}</aside></div></>}</>
}
function FindingCard({ finding, workspace, onResolve, busy }: { finding: Finding; workspace: Workspace; onResolve: () => void; busy: boolean }) {
  return <article className={`finding-card finding-${finding.severity}`}><div className="finding-head"><span className={`severity-mark severity-${finding.severity}`}>{finding.severity === 'high' ? '!' : finding.severity === 'info' ? 'i' : '•'}</span><div><span className="finding-category">{finding.category.replaceAll('_', ' ')}</span><h3>{finding.explanation}</h3></div><StatusPill status={finding.severity} /></div><blockquote>{finding.quoted}</blockquote><div className="finding-action"><b>Suggested next step</b><p>{finding.action}</p></div>{finding.evidence?.length ? <div className="evidence-block"><div className="eyebrow">SUPPORTING EVIDENCE</div>{finding.evidence.map((e, i) => <div className="evidence-quote" key={i}><span>“</span><p>{e.snippet || 'The API returned an evidence record without an excerpt.'}</p>{e.source_url && <a href={e.source_url} target="_blank" rel="noreferrer">Open source ↗</a>}</div>)}</div> : <div className="evidence-unavailable"><span>i</span> No source excerpt was returned for this finding.</div>}{finding.status !== 'resolved' && <button className="button button-secondary button-xs" disabled={busy || workspace.role !== 'owner' && workspace.role !== 'reviewer'} title={workspace.role !== 'owner' && workspace.role !== 'reviewer' ? 'Only owners and reviewers can resolve findings.' : undefined} onClick={onResolve}>Mark resolved with rationale</button>}</article>
}

function ImpactQueue({ workspace }: { workspace: Workspace }) {
  const list = useLoad(() => impactApi.list(workspace.id), [workspace.id]); const impacts = list.data ?? []; const pending = impacts.filter(i => i.state === 'needs_review')
  return <><PageHeading eyebrow="DEPENDENCY-BASED REVIEW" title="Fact change queue" subtitle="Review content linked to changed facts or rules. A new review and a human decision clear each impact." action={<button className="button button-secondary button-small" onClick={list.refresh}>↻ Refresh</button>} /><Panel className="impact-panel"><div className="panel-heading"><div><h2>Items for human review</h2><p>Only recorded dependencies appear here. A changed fact does not automatically mark content incorrect.</p></div><span className="panel-counter">{list.data ? pending.length : '—'}</span></div><LoadState loading={list.loading} error={list.error} empty={!impacts.length} onRetry={list.refresh} />{!list.loading && !list.error && (impacts.length ? <div className="impact-list">{impacts.map(item => <ImpactCard key={item.id} item={item} />)}</div> : <EmptyState icon="↻" title="No fact changes to review" body="When a new approved fact or rule affects reviewed content, its dependency appears here." />)}</Panel></>
}
function ImpactCard({ item }: { item: Impact }) {
  return <article className="impact-row"><div className="impact-symbol">↻</div><div className="impact-main"><div className="impact-title-row"><b>{item.source} · submission {item.sub.slice(0, 10)}</b><StatusPill status={item.state} /></div><p>{item.state === 'needs_review' ? 'Re-run the review on the current version, then record a human decision to resolve this impact.' : 'This impact was resolved by a later decision.'}</p><div className="version-compare"><span><small>PREVIOUS VERSION</small><code>{item.old_version}</code></span><span className="compare-arrow">→</span><span><small>NEW VERSION</small><code>{item.new_version}</code></span></div>{item.rationale && <div className="impact-rationale">{item.rationale}</div>}</div></article>
}function AuditPage({ workspace }: { workspace: Workspace }) {
  const list = useLoad(() => auditApi.list(workspace.id), [workspace.id]); const events = list.data ?? []
  return <><PageHeading eyebrow="APPEND-ONLY HISTORY" title="Audit trail" subtitle="Trace important changes and decisions recorded by the workspace API." action={<button className="button button-secondary button-small" onClick={list.refresh}>↻ Refresh</button>} /><div className="audit-notice"><span>⌁</span><div><b>Workspace owner access</b><p>Audit events are visible to workspace members. API authorization applies even when this page is hidden.</p></div></div><Panel className="audit-panel"><LoadState loading={list.loading} error={list.error} empty={!events.length} onRetry={list.refresh} />{!list.loading && !list.error && (events.length ? <div className="audit-list">{events.map((event, i) => <AuditRow key={event.id} event={event} last={i === events.length - 1} />)}</div> : <EmptyState icon="⌁" title="No audit events yet" body="Changes and decisions will appear here when recorded by the API. This history is never replaced with sample activity." />)}</Panel></>
}
function AuditRow({ event, last }: { event: AuditEvent; last: boolean }) { const names: Record<string, string> = { 'workspace.create': 'Workspace created', 'member.add': 'Workspace member added', 'source.create': 'Brand fact created', 'source.version.create': 'Brand fact version added', 'source.approve': 'Brand fact approved', 'impact.flag': 'Submission flagged for review', 'impact.dismiss': 'Impact marked not affected', 'review.run': 'Brand check completed', 'submission.create': 'Submission created', 'submission.submit': 'Submitted for review', 'review.decision': 'Review decision recorded', 'revision.create': 'Submission revision created', 'finding.resolve': 'Finding resolved' }; return <div className="audit-row"><div className="audit-timeline"><span className="audit-dot" />{!last && <span className="audit-line" />}</div><div className="audit-event"><div className="audit-event-top"><b>{names[event.action] ?? event.action.replaceAll('.', ' ')}</b><time>{new Date(event.created).toLocaleString()}</time></div><p>{event.action} · Record <code>{event.target.slice(0, 12)}</code></p>{Object.keys(event.detail).length > 0 && <details><summary>Event details</summary><pre>{JSON.stringify(event.detail, null, 2)}</pre></details>}<small>Actor ID · {event.actor.slice(0, 10)}</small></div></div> }

function TeamPage({ workspace }: { workspace: Workspace }) {
  const list = useLoad(() => teamApi.list(workspace.id), [workspace.id]); const action = useAction(); const [email, setEmail] = useState(''); const [role, setRole] = useState('reviewer'); const canManage = workspace.role === 'owner'
  const add = async (e: FormEvent) => { e.preventDefault(); if (!email.includes('@')) { action.run(async () => { throw new Error('Enter a valid email address for a registered user.') }); return } const ok = await action.run(() => teamApi.add(workspace.id, email.trim(), role), 'Member added to the workspace.'); if (ok) { setEmail(''); list.refresh() } }
  return <><PageHeading eyebrow="ROLE-BASED ACCESS" title="People & access" subtitle="Workspace membership and permissions are enforced by the API." action={<span className="role-chip">Your role · {workspace.role.replace('_', ' ')}</span>} /><Feedback error={action.error} notice={action.notice} /><div className="team-layout"><Panel><div className="panel-heading"><div><h2>Workspace members</h2><p>People currently authorized in this workspace</p></div><span className="panel-counter">{list.data?.length ?? '—'}</span></div><LoadState loading={list.loading} error={list.error} empty={!list.data?.length} onRetry={list.refresh} />{!list.loading && !list.error && (list.data?.length ? <div className="member-list">{list.data.map(m => <MemberRow key={m.user_id} member={m} />)}</div> : <EmptyState title="Could not find workspace members" body="The membership endpoint returned no records." />)}</Panel><Panel className="invite-panel"><div className="form-panel-header"><span className="form-panel-icon">♧</span><div><h2>Add a member</h2><p>The person needs an existing Proofline account.</p></div></div>{canManage ? <form className="form-stack" onSubmit={add}><Field label="Account email" value={email} onChange={setEmail} placeholder="person@company.com" type="email" /><label className="field"><span>Workspace role</span><select value={role} onChange={e => setRole(e.target.value)}>{[['owner', 'Owner'], ['editor', 'Editor'], ['reviewer', 'Reviewer']].map(([v, label]) => <option key={v} value={v}>{label}</option>)}</select></label><div className="form-hint"><span>i</span><span>Owners and editors can create or approve brand fact versions. Reviewers record human decisions.</span></div><button className="button button-primary button-wide" disabled={action.busy}>{action.busy ? 'Adding…' : 'Add member'} <span>→</span></button></form> : <div className="unavailable-box"><span className="unavailable-icon">⌑</span><div><b>Owner permissions required</b><p>Your current role does not allow membership changes.</p></div></div>}</Panel></div></>
}
function MemberRow({ member }: { member: Member }) { return <div className="member-row"><div className="avatar member-avatar">{member.name.trim().slice(0, 1).toUpperCase()}</div><div className="member-copy"><b>{member.name}</b><span>{member.email}</span></div><span className="role-chip">{member.role.replace('_', ' ')}</span></div> }
